internal final class JSGFMCustomerEvents
{

    private static boolean firstLoad = true;





}

Method.Source:
    [FormEventHandler(formStr(JSGVendGroupForm),
                  FormEventType::Initialized)]
public static void JSGVendGroupForm_OnInitialized(xFormRun sender,
                                                  FormEventArgs e)
    {






        FormComboBoxControl cmbCompany;

        cmbCompany =
        sender.design().controlName("CmbCompany");

        cmbCompany.add("Seleccione");
        cmbCompany.add("DAT");
        cmbCompany.add("USMF");

        cmbCompany.selection(1);


    }

[FormDataSourceEventHandler(formDataSourceStr(JSGVendGroupForm, FMCustomer),
                            FormDataSourceEventType::Activated)]
public static void FMCustomer_OnActivated(FormDataSource sender,
                                          FormDataSourceEventArgs e)
{
    FMCustomer customer;
    FormRun formRun;

    FormStringControl txtFirstName;
    FormStringControl txtLastName;
    FormStringControl txtCellPhone;
    FormStringControl txtEmail;

    formRun = sender.formRun();

    txtFirstName = formRun.design().controlName("TxtFirstName");
    txtLastName  = formRun.design().controlName("TxtLastName");
    txtCellPhone = formRun.design().controlName("TxtCellPhone");
    txtEmail     = formRun.design().controlName("TxtEmail");

    // Primera carga del formulario
    if (JSGFMCustomerEvents::firstLoad)
    {
        JSGFMCustomerEvents::firstLoad = false;

        txtFirstName.text("");
        txtLastName.text("");
        txtCellPhone.text("");
        txtEmail.text("");

        return;
    }

    customer = sender.cursor();

    txtFirstName.text(customer.FirstName);
    txtLastName.text(customer.LastName);
    txtCellPhone.text(customer.CellPhone);
    txtEmail.text(customer.Email);
}

