/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(JSGVendGroupForm, BtnGuardar), FormControlEventType::Clicked)]
public static void BtnGuardar_OnClicked(FormControl sender, FormControlEventArgs e)
{
    info("Entró al botón guardar");

    FormRun formRun = sender.formRun();

    FormStringControl txtFirstName =
    formRun.design().controlName("TxtFirstName");

    FormStringControl txtLastName =
    formRun.design().controlName("TxtLastName");

    FormStringControl txtCellPhone =
    formRun.design().controlName("TxtCellPhone");

    FormStringControl txtEmail =
    formRun.design().controlName("TxtEmail");

    // VALIDACIONES
    if (txtFirstName.text() == "")
    {
        warning("Debe ingresar el nombre.");
        return;
    }

    if (txtLastName.text() == "")
    {
        warning("Debe ingresar el apellido.");
        return;
    }

    if (txtCellPhone.text() == "")
    {
        warning("Debe ingresar el teléfono.");
        return;
    }

    if (txtEmail.text() == "")
    {
        warning("Debe ingresar el correo electrónico.");
        return;
    }

    if (!strScan(txtEmail.text(), "@", 1, strLen(txtEmail.text())))
    {
        warning("Debe ingresar un correo válido.");
        return;
    }

    FMCustomer customer;

    ttsbegin;

    customer.FirstName = txtFirstName.text();
    customer.LastName  = txtLastName.text();
    customer.CellPhone = txtCellPhone.text();
    customer.Email     = txtEmail.text();

    FMCustomer customerExist;

    select firstOnly customerExist
where customerExist.FirstName == txtFirstName.text()
   && customerExist.LastName  == txtLastName.text();

    if (customerExist.RecId)
    {
        warning("Ya existe un cliente con este nombre y apellido.");
        return;
    }

    select firstOnly customerExist
where customerExist.Email == txtEmail.text();

    if (customerExist.RecId)
    {
        warning("Ya existe un cliente con este correo electrónico.");
        return;
    }

    try
    {

    customer.insert();

    }
    catch (Exception::DuplicateKeyException)
    {
        warning("El cliente ya existe.");
        return;
    }

    ttscommit;

    info("Cliente guardado correctamente.");

    // Refrescar la grilla
    FormDataSource fmCustomerDs;

    fmCustomerDs =
formRun.dataSource(
    formDataSourceStr(JSGVendGroupForm, FMCustomer));

    fmCustomerDs.executeQuery();

}

