/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(JSGVendGroupForm, BtnActualizar), FormControlEventType::Clicked)]
public static void BtnActualizar_OnClicked(FormControl sender, FormControlEventArgs e)
{

    FormRun formRun = sender.formRun();

    FormStringControl txtFirstName =
    formRun.design().controlName("TxtFirstName");

    FormStringControl txtLastName =
    formRun.design().controlName("TxtLastName");

    FormStringControl txtCellPhone =
    formRun.design().controlName("TxtCellPhone");

    FormStringControl txtEmail =
    formRun.design().controlName("TxtEmail");

    FormDataSource fmCustomerDs =
    formRun.dataSource(
        formDataSourceStr(JSGVendGroupForm, FMCustomer));

    FMCustomer customer;

    customer = fmCustomerDs.cursor();

    if (!customer.RecId)
    {
        warning("Debe seleccionar un registro.");
        return;
    }

    if (txtFirstName.text() == "")
    {
        warning("Debe ingresar el nombre.");
        return;
    }

    if (txtLastName.text() == "")
    {
        warning("Debe ingresar el apellido.");
        return;
    }

    if (txtCellPhone.text() == "")
    {
        warning("Debe ingresar el teléfono.");
        return;
    }

    if (txtEmail.text() == "")
    {
        warning("Debe ingresar el correo electrónico.");
        return;
    }

    ttsbegin;

    customer.selectForUpdate(true);

    customer.FirstName = txtFirstName.text();
    customer.LastName  = txtLastName.text();
    customer.CellPhone = txtCellPhone.text();
    customer.Email     = txtEmail.text();

    customer.update();

    ttscommit;

    info("Cliente actualizado correctamente.");

    fmCustomerDs.executeQuery();
}

/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(JSGVendGroupForm, BtnEliminar), FormControlEventType::Clicked)]
public static void BtnEliminar_OnClicked(FormControl sender, FormControlEventArgs e)
{
    DialogButton respuesta;

    FormRun formRun = sender.formRun();

    FormDataSource fmCustomerDs =
    formRun.dataSource(
        formDataSourceStr(JSGVendGroupForm, FMCustomer));

    FMCustomer customer =
    fmCustomerDs.cursor();

    if (!customer.RecId)
    {
        warning("Debe seleccionar un registro.");
        return;
    }

    respuesta = Box::yesNo(
    strFmt("¿Desea eliminar el cliente %1 %2?",
           customer.FirstName,
           customer.LastName),
    DialogButton::No,
    "Confirmar eliminación");

    if (respuesta == DialogButton::Yes)
    {
        ttsbegin;

        customer.selectForUpdate(true);
        customer.delete();

        ttscommit;

        info("Cliente eliminado correctamente.");

        fmCustomerDs.executeQuery();
    }
}
